def _setup():
    libc = ctypes.CDLL(None)
    libc._dyld_image_count.restype = ctypes.c_uint32
    libc._dyld_get_image_name.restype = ctypes.c_char_p
    libc._dyld_get_image_header.restype = ctypes.c_void_p
    libc.getsectiondata.restype = ctypes.c_void_p
    libc.getsectiondata.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_char_p, ctypes.POINTER(ctypes.c_ulong)]
    def table(sub):
        for i in range(libc._dyld_image_count()):
            if sub in libc._dyld_get_image_name(i):
                h = libc._dyld_get_image_header(i)
                sz = ctypes.c_ulong()
                p = libc.getsectiondata(h, b'__DATA', b'__la_symbol_ptr', ctypes.byref(sz))
