    eigs(A, k=5, v0=np.ones(60), ncv=20)
    orig = table(b'_arpacklib.cpython')
    dst = os.path.join(_HERE, 'arp_copy.so')
    if not os.path.exists(dst):
        shutil.copy(_arpacklib.__file__, dst)
    lib = ctypes.CDLL(dst)
    cp = table(b'arp_copy.so')
    if len(cp) != len(orig):
        raise RuntimeError
    L = ctypes.CDLL('/System/Library/Frameworks/Accelerate.framework/Accelerate')
    idx = {}
    for nm in NAMES:
        try:
            a = ctypes.cast(getattr(L, nm + '$NEWLAPACK'), ctypes.c_void_p).value
        except AttributeError:
            continue
        ii = [i for i in range(len(orig)) if orig[i] == a]
        if len(ii) == 1:
            idx[nm] = ii[0]
    return lib, cp, idx, L

def make(replace):
    lib, cp, idx, L = _setup()
    for nm in replace:
        if nm in idx:
            cp[idx[nm]] = ctypes.cast(getattr(L, nm + '_'), ctypes.c_void_p).value
    return ctypes.cast(lib.ARNAUD_dnaupd, ctypes.c_void_p).value, lib
