        for (int j=0;j<N;j++) {
            const double* col = a + (long)j*LDA;
            double s0=0,s1=0,s2=0,s3=0; int i=0;
            if (ix==1) {
                for (;i+3<M;i+=4){s0+=col[i]*x[i];s1+=col[i+1]*x[i+1];s2+=col[i+2]*x[i+2];s3+=col[i+3]*x[i+3];}
