typedef void (*fn_t)(void*, double*, double*, int, int*, double*, double*);

/* ELL with groups of 4 rows: glen[g] steps, idx/val stored [step][4] contiguous per group */
static void ellmv(int ng, const int* glen, const int* idx, const double* val, const int* rowof,
                  const double* x, double* y) {
    long off = 0;
    int g = 0;
    for (; g + 1 < ng; g += 2) {
        int L0 = glen[g], L1 = glen[g+1];
        const int* i0 = idx + off; const double* v0 = val + off;
        const int* i1 = idx + off + (long)L0*4; const double* v1 = val + off + (long)L0*4;
        __m256d a0 = _mm256_setzero_pd(), a1 = _mm256_setzero_pd();
        int mn = L0 < L1 ? L0 : L1;
        int t = 0;
        for (; t < mn; t++) {
            __m128i q0 = _mm_loadu_si128((const __m128i*)(i0 + 4*t));
            __m128i q1 = _mm_loadu_si128((const __m128i*)(i1 + 4*t));
            __m256d x0 = _mm256_i32gather_pd(x, q0, 8);
            __m256d x1 = _mm256_i32gather_pd(x, q1, 8);
            a0 = _mm256_add_pd(a0, _mm256_mul_pd(_mm256_loadu_pd(v0 + 4*t), x0));
            a1 = _mm256_add_pd(a1, _mm256_mul_pd(_mm256_loadu_pd(v1 + 4*t), x1));
        }
        for (int u = t; u < L0; u++) {
            __m128i q0 = _mm_loadu_si128((const __m128i*)(i0 + 4*u));
            a0 = _mm256_add_pd(a0, _mm256_mul_pd(_mm256_loadu_pd(v0 + 4*u), _mm256_i32gather_pd(x, q0, 8)));
