            __m128i q1 = _mm_loadu_si128((const __m128i*)(i1 + 4*u));
            a1 = _mm256_add_pd(a1, _mm256_mul_pd(_mm256_loadu_pd(v1 + 4*u), _mm256_i32gather_pd(x, q1, 8)));
        }
        double s[8];
        _mm256_storeu_pd(s, a0); _mm256_storeu_pd(s+4, a1);
        const int* ro = rowof + 4*g;
        for (int r = 0; r < 8; r++) if (ro[r] >= 0) y[ro[r]] = s[r];
        off += (long)(L0 + L1) * 4;
    }
    for (; g < ng; g++) {
