        }
        double s[4]; _mm256_storeu_pd(s, a0);
        const int* ro = rowof + 4*g;
        for (int r = 0; r < 4; r++) if (ro[r] >= 0) y[ro[r]] = s[r];
        off += (long)L0 * 4;
    }
}

/* build ELL; perm = rows sorted by length desc; returns total steps*4 written */
long build(int n, const int* indptr, const int* indices, const double* data, const int* perm,
           int* glen, int* idx, double* val, int* rowof) {
    int ng = (n + 3) / 4; long off = 0;
    for (int g = 0; g < ng; g++) {
        int L = 0;
        for (int r = 0; r < 4; r++) {
            int k = 4*g + r;
            if (k < n) { int ro = perm[k]; rowof[k] = ro; int l = indptr[ro+1]-indptr[ro]; if (l > L) L = l; }
            else rowof[k] = -1;
        }
        glen[g] = L;
        for (int t = 0; t < L; t++)
            for (int r = 0; r < 4; r++) {
                int k = 4*g + r; long p = off + 4L*t + r;
                if (k < n) {
                    int ro = perm[k];
                    if (t < indptr[ro+1]-indptr[ro]) { idx[p] = indices[indptr[ro]+t]; val[p] = data[indptr[ro]+t]; continue; }
                }
                idx[p] = 0; val[p] = 0.0;
            }
        off += 4L*L;
    }
    return off;
}

